import { useState, useEffect, useRef } from "react";

export function SearchBox({ search, debounceMs = 300, minChars = 2 }) {
  const [value, setValue] = useState("");
  const [results, setResults] = useState([]);
  const [status, setStatus] = useState("");
  const [error, setError] = useState(false);
  const latestQueryRef = useRef("");
  const abortControllerRef = useRef(null);
  const debounceTimerRef = useRef(null);

  useEffect(() => {
    return () => {
      clearTimeout(debounceTimerRef.current);
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, []);

  const handleSearch = (query) => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;
    setStatus("Searching...");
    setError(false);

    search(query, { signal: controller.signal })
      .then((data) => {
        if (latestQueryRef.current === query) {
          setResults(data);
          setStatus(data.length === 0 ? "No results" : "");
        }
      })
      .catch((err) => {
        if (err.name !== "AbortError" && latestQueryRef.current === query) {
          setResults([]);
          setError(true);
        }
      });
  };

  const handleChange = (e) => {
    const newValue = e.target.value;
    setValue(newValue);
    const trimmedQuery = newValue.trim();

    if (trimmedQuery.length < minChars) {
      clearTimeout(debounceTimerRef.current);
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
      setResults([]);
      setStatus("");
      setError(false);
      return;
    }

    if (trimmedQuery === latestQueryRef.current && status !== "Searching...") {
      return;
    }

    clearTimeout(debounceTimerRef.current);
    debounceTimerRef.current = setTimeout(() => {
      latestQueryRef.current = trimmedQuery;
      handleSearch(trimmedQuery);
    }, debounceMs);
  };

  const handleRetry = () => {
    const trimmedQuery = value.trim();
    if (trimmedQuery.length >= minChars) {
      latestQueryRef.current = trimmedQuery;
      handleSearch(trimmedQuery);
    }
  };

  return (
    <div>
      <input
        type="search"
        aria-label="Search"
        value={value}
        onChange={handleChange}
      />
      <div role="status">{status}</div>
      {error && (
        <div role="alert">
          Something went wrong
          <button onClick={handleRetry}>Retry</button>
        </div>
      )}
      <ul aria-label="Results">
        {results.map((result, index) => (
          <li key={index}>{result}</li>
        ))}
      </ul>
    </div>
  );
}
